using System.ComponentModel;
using System.Net.Http.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for the given resource ID.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The resource ID to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching data for resource {ResourceId}", resourceId);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            logger.LogWarning("API returned {StatusCode} for resource {ResourceId}",
                response.StatusCode, resourceId);
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Successfully fetched {Length} bytes for resource {ResourceId}",
            content.Length, resourceId);

        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Summarizes the provided text into a concise overview.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Target length: short, medium, or long")] string length = "medium")
    {
        var systemInstruction = length.ToLowerInvariant() switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "long" => "Provide a detailed summary of the following text, preserving key details.",
            _ => "Summarize the following text in a concise paragraph."
        };

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"{systemInstruction}\n\n{text}")
        ];
    }
}

