using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Summarizes the provided text into a concise overview.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Target length: short, medium, or long")] string length = "medium")
    {
        var systemInstruction = length.ToLowerInvariant() switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "long" => "Provide a detailed summary of the following text, preserving key details.",
            _ => "Summarize the following text in a concise paragraph."
        };

        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"{systemInstruction}\n\n{text}")
        ];
    }
}
